import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"2004年 · 贸易之忧","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2004年.md","filePath":"05_quotes/by-year/2004年.md"}'),r={name:"05_quotes/by-year/2004年.md"};function u(c,e,q,p,s,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2004年-·-贸易之忧" tabindex="-1">2004年 · 贸易之忧 <a class="header-anchor" href="#_2004年-·-贸易之忧" aria-label="Permalink to &quot;2004年 · 贸易之忧&quot;">​</a></h1><blockquote><p>投资者应该记住，兴奋和费用是他们的敌人。如果他们坚持要择时参与股市，应该在别人贪婪时恐惧，在别人恐惧时贪婪。——巴菲特（74岁）</p></blockquote><p>本页收录2004年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>只有当潮水退去时，你才会知道谁在裸泳。</p></blockquote><blockquote><p>如同地狱一般，衍生品交易容易进入但难以退出。（其他相似之处也会浮现。）</p></blockquote><blockquote><p>我们将持仓视为企业的部分所有权。这是一个重要的区别。实际上，这一思考方式是我自19岁以来投资行为的基石。</p></blockquote><blockquote><p>如果不是人，他们不会被诱惑去阻止可能威胁其生计的行动。</p></blockquote><blockquote><p>简单的事实是，某些CEO知道如果期权被计入费用，他们的薪酬会被更理性地确定。</p></blockquote><blockquote><p>一个现在追求&quot;所有者社会&quot;的国家不会在&quot;佃农社会&quot;中找到幸福。但这恰恰是我们的贸易政策正在把我们带向的地方。</p></blockquote><blockquote><p>儿子们将真正为父亲的罪过付出代价。</p></blockquote><blockquote><p>斯密先生指的是产品换产品，而不是像我们国家目前每年以6000亿美元的方式做的那样，用财富换产品。</p></blockquote><blockquote><p>绵羊作为一个阶层可能被嘲笑，但单个绵羊从不被批评。</p></blockquote><blockquote><p>我该行动时却只是空谈。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2004年伯克希尔每股账面价值增长10.5%，微弱落后标普500。巴菲特未能完成重大收购，年底持有430亿美元现金，直言&quot;不是令人愉快的处境&quot;。他大幅扩展外汇头寸至214亿美元，并对美国巨额贸易逆差发出严厉警告，预言&quot;佃农社会&quot;的到来。本年他还深刻反思了在泡沫期间&quot;只是空谈&quot;而未行动的失误。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2004年/翻译.html">01_letters/2004年/翻译</a> · <a href="/01_letters/2004年/核心总结.html">01_letters/2004年/核心总结</a> · <a href="/01_letters/2004年/思维导图.html">01_letters/2004年/思维导图</a></p>',21)])])}const k=t(r,[["render",u]]);export{h as __pageData,k as default};
